namespace sv_0b52da9fef9947a18db29f422131d797.Services;

/// <summary>
/// Scoped service that holds the currently selected warehouse for a single circuit (user session).
/// Components subscribe to OnChange to react when the selection changes.
/// </summary>
public class WarehouseStateService
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId
    {
        get => _currentWarehouseId;
        set
        {
            if (_currentWarehouseId == value) return;
            _currentWarehouseId = value;
            NotifyStateChanged();
        }
    }

    public string CurrentWarehouseName =>
        AvailableWarehouses.FirstOrDefault(w => w.Id == _currentWarehouseId)?.Name ?? "Unknown";

    public IReadOnlyList<Warehouse> AvailableWarehouses { get; } = new List<Warehouse>
    {
        new("WH-001", "Warehouse A — East"),
        new("WH-002", "Warehouse B — West"),
        new("WH-003", "Warehouse C — Central"),
        new("WH-004", "Warehouse D — North"),
    };

    public event Action? OnChange;

    private void NotifyStateChanged() => OnChange?.Invoke();
}

public record Warehouse(string Id, string Name);

namespace sv_0b52da9fef9947a18db29f422131d797.Services;

/// <summary>
/// Scoped service that provides low-stock alert counts and notifies all subscribers
/// when new data arrives. Each circuit (user) gets its own instance.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();
    private Timer? _pollingTimer;
    private int _subscriberCount;
    private int _lastKnownCount;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChanged;
    }

    public int CurrentAlertCount => _lastKnownCount;

    /// <summary>
    /// Fired when new alert data is available. All subscribed components should re-render.
    /// </summary>
    public event Func<Task>? OnAlertDataChanged;

    /// <summary>
    /// Simulates a database query returning low-stock item count for a warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Called by components that want polling to be active. Polling starts on first subscriber.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            _pollingTimer = new Timer(PollCallback, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
        }
    }

    /// <summary>
    /// Called when a component no longer needs polling. Polling stops when no subscribers remain.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _pollingTimer?.Dispose();
            _pollingTimer = null;
        }
    }

    private async void PollCallback(object? state)
    {
        var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        _lastKnownCount = count;
        await NotifySubscribers();
    }

    private async void HandleWarehouseChanged()
    {
        // When warehouse changes, immediately refresh alert data
        if (_pollingTimer is not null)
        {
            var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
            _lastKnownCount = count;
            await NotifySubscribers();
        }
    }

    private async Task NotifySubscribers()
    {
        if (OnAlertDataChanged is not null)
        {
            await OnAlertDataChanged.Invoke();
        }
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= HandleWarehouseChanged;
        _pollingTimer?.Dispose();
    }
}

