@page "/dashboard"
@rendermode InteractiveServer
@using sv_0b52da9fef9947a18db29f422131d797.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard — @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="lead">Viewing: <strong>@WarehouseState.CurrentWarehouseName</strong></p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card @(AlertService.CurrentAlertCount > 5 ? "border-danger" : "border-success")">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="display-4 @(AlertService.CurrentAlertCount > 5 ? "text-danger" : "text-success")">
                    @AlertService.CurrentAlertCount
                </p>
                <p class="text-muted small">
                    Items below minimum level at @WarehouseState.CurrentWarehouseName
                </p>
                <p class="text-muted small fst-italic">
                    Auto-refreshes every 10 seconds
                </p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Selected Warehouse</h5>
                <p class="display-6">@WarehouseState.CurrentWarehouseId</p>
                <p class="text-muted small">@WarehouseState.CurrentWarehouseName</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="display-6 text-success">Active</p>
                <p class="text-muted small">
                    Polling stops when you leave this page
                </p>
            </div>
        </div>
    </div>
</div>

<div class="mt-4 p-3 bg-light rounded">
    <h5>How This Works</h5>
    <ul class="mb-0">
        <li>The <strong>WarehouseSelector</strong> in the top bar updates a shared scoped service.</li>
        <li>This dashboard and the sidebar badge both subscribe to <code>InventoryAlertService.OnAlertDataChanged</code>.</li>
        <li>Polling runs every 10 seconds while this page is active and notifies <em>all</em> subscribers.</li>
        <li>Each user circuit gets its own service instances — switching warehouses here won't affect other users.</li>
    </ul>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleStateChanged;
        AlertService.OnAlertDataChanged += HandleAlertDataChanged;
        AlertService.StartPolling();
    }

    private void HandleStateChanged() => InvokeAsync(StateHasChanged);

    private async Task HandleAlertDataChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleStateChanged;
        AlertService.OnAlertDataChanged -= HandleAlertDataChanged;
        AlertService.StopPolling();
    }
}

